import os, pytest
from impl import run

def mk(tmp_path,monkeypatch,bank_rows):
    d=tmp_path/'inbox'/'f'; d.mkdir(parents=True)
    (d/'purchase_orders.csv').write_text('po_number,supplier,order_date,sku,description,qty,unit_price_czk\nPO-1,A s.r.o.,2026-01-01,X,x,10,100.00\n',encoding='utf-8')
    (d/'bank_statement.csv').write_text('Datum;Částka;Měna;Protistrana;VS;Zpráva;Zůstatek\n'+bank_rows,encoding='utf-8')
    monkeypatch.chdir(tmp_path)

def inv(**k):
    b={'file':'a.txt','supplier':'A s.r.o.','invoice_number':'A1','vs':'1','po_number':'PO-1','items':[{'code':'X','qty':10.0,'unit_price':100.0,'amount':1000.0}],'total':1210.0,'resent':False}
    b.update(k); return b

def test_double_payment(tmp_path,monkeypatch):
    mk(tmp_path,monkeypatch,'01.02.2026;-1 210,00;CZK;A s.r.o.;1;x;1\n05.02.2026;-1 210,00;CZK;A s.r.o.;1;x;1\n')
    r=run({'folder':'f','invoices':[inv()]})
    assert [f['type'] for f in r['findings']]==['double_payment']
    assert r['findings'][0]['bank_dates']==['2026-02-01','2026-02-05']

def test_mismatch_and_noorder(tmp_path,monkeypatch):
    mk(tmp_path,monkeypatch,'')
    i=inv(items=[{'code':'X','qty':12.0,'unit_price':120.0}])
    r=run({'folder':'f','invoices':[i,inv(invoice_number='B',po_number='-',supplier=None)]})
    t={f['type'] for f in r['findings']}
    assert t=={'price_mismatch','quantity_mismatch','no_order'}

def test_duplicate(tmp_path,monkeypatch):
    mk(tmp_path,monkeypatch,'')
    r=run({'folder':'f','invoices':[inv(),inv(file='b.txt',resent=True)],'checks':['duplicates']})
    assert len(r['findings'])==1 and r['findings'][0]['type']=='duplicate'

def test_bad_input(tmp_path,monkeypatch):
    monkeypatch.chdir(tmp_path)
    with pytest.raises(ValueError): run({'folder':'nope','invoices':[]})
    with pytest.raises(ValueError): run({'folder':'f','invoices':'x'})

