import csv, io, os, re
from pathlib import Path

ALL = ['duplicate', 'price_mismatch', 'quantity_mismatch', 'no_order', 'double_payment', 'payment_mismatch']

def num(s):
    if s is None: return None
    s = str(s).replace('\xa0', '').replace(' ', '').replace('\u202f', '')
    if not s: return None
    if ',' in s: s = s.replace('.', '').replace(',', '.')
    try: return float(s)
    except ValueError: return None

def iso(d):
    d = (d or '').strip()
    m = re.match(r'^(\d{1,2})\.(\d{1,2})\.(\d{4})$', d)
    return f'{m[3]}-{int(m[2]):02d}-{int(m[1]):02d}' if m else d

def read_csv(p):
    txt = Path(p).read_text(encoding='utf-8-sig')
    first = txt.splitlines()[0] if txt.strip() else ''
    dl = ';' if first.count(';') > first.count(',') else ','
    rows = list(csv.DictReader(io.StringIO(txt), delimiter=dl))
    return [{(k or '').strip().lower(): (v or '').strip() for k, v in r.items()} for r in rows]

def pick(r, *names):
    for n in names:
        if n in r: return r[n]
    return ''

def norm_vs(v): return re.sub(r'\D', '', str(v or '')).lstrip('0')

def r2(x): return round(x + 0.0, 2)

def run(inp):
    if not isinstance(inp, dict): raise ValueError('input must be an object')
    folder = inp.get('folder'); invs = inp.get('invoices')
    if not folder or not isinstance(folder, str): raise ValueError('folder is required')
    if not isinstance(invs, list): raise ValueError('invoices must be a list')
    checks = inp.get('checks') or ALL
    if not isinstance(checks, list): raise ValueError('checks must be a list')
    base = Path('inbox') / folder
    if not base.is_dir(): raise ValueError(f'folder not found: {base}')
    problems = []
    pos = {}
    pf = base / 'purchase_orders.csv'
    if pf.exists():
        try:
            for r in read_csv(pf):
                n = pick(r, 'po_number')
                pos.setdefault(n, []).append(r)
        except Exception as e: problems.append(f'purchase_orders.csv: {e}')
    else: problems.append('purchase_orders.csv missing')
    bank = []
    bf = base / 'bank_statement.csv'
    if bf.exists():
        try:
            for r in read_csv(bf):
                a = num(pick(r, 'částka', 'castka', 'amount'))
                if a is None: continue
                bank.append({'file': bf.name, 'date': iso(pick(r, 'datum', 'date')), 'amount': a,
                             'vs': pick(r, 'vs'), 'counterparty': pick(r, 'protistrana'), 'message': pick(r, 'zpráva', 'zprava')})
        except Exception as e: problems.append(f'bank_statement.csv: {e}')
    else: problems.append('bank_statement.csv missing')
    sf = (inp.get('supplier_filter') or '').strip().lower()
    invs = [i for i in invs if isinstance(i, dict) and (not sf or sf in str(i.get('supplier', '')).lower())]
    findings = []
    groups = {}
    for i in invs:
        groups.setdefault((str(i.get('supplier', '')).lower(), str(i.get('invoice_number', ''))), []).append(i)
    def brows(vs):
        k = norm_vs(vs)
        return [{kk: b[kk] for kk in ('file', 'date', 'amount', 'vs', 'counterparty', 'message')} for b in bank if k and norm_vs(b['vs']) == k and b['amount'] < 0]
    def add(t, inv, files, **kw):
        f = {'type': t, 'invoice_number': str(inv.get('invoice_number', '')), 'invoice_files': files,
             'po_number': str(inv.get('po_number') or ''), 'po_lines': [], 'invoice_items': [], 'bank_rows': [],
             'expected': None, 'actual': None, 'difference_czk': None, 'detail': ''}
        f.update(kw); findings.append(f)
    for key, grp in groups.items():
        files = [g.get('file', '') for g in grp]
        inv = next((g for g in grp if not g.get('resent')), grp[0])
        total = num(inv.get('total')) if not isinstance(inv.get('total'), (int, float)) else float(inv['total'])
        br = brows(inv.get('vs'))
        if len(grp) > 1 and 'duplicate' in checks:
            add('duplicate', inv, files, bank_rows=br, expected=1, actual=len(grp), difference_czk=r2(total or 0) if total else None,
                detail=f'Invoice {inv.get("invoice_number")} received {len(grp)} times ({", ".join(files)}); payable once')
        po = str(inv.get('po_number') or '').strip()
        lines = pos.get(po) if po not in ('', '-') else None
        if not lines:
            if 'no_order' in checks:
                add('no_order', inv, files, bank_rows=br, invoice_items=inv.get('items') or [], expected=0, actual=total,
                    difference_czk=total, detail='No purchase order reference' if po in ('', '-') else f'PO {po} not found in purchase_orders.csv')
        else:
            for it in inv.get('items') or []:
                code = it.get('code')
                idx = [n for n, l in enumerate(lines, 1) if pick(l, 'sku') == code]
                if not idx:
                    if 'no_order' in checks:
                        add('no_order', inv, files, invoice_items=[it], bank_rows=br, expected=0, actual=it.get('amount'),
                            difference_czk=it.get('amount'), detail=f'Item {code} not on PO {po}')
                    continue
                l = lines[idx[0] - 1]
                pl = {'po_number': po, 'line': idx[0], 'sku': code, 'description': pick(l, 'description'),
                      'qty': num(pick(l, 'qty')), 'unit_price': num(pick(l, 'unit_price_czk'))}
                q = float(it.get('qty') or 0); up = float(it.get('unit_price') or 0)
                if pl['unit_price'] is not None and abs(up - pl['unit_price']) > 0.005 and 'price_mismatch' in checks:
                    add('price_mismatch', inv, files, po_lines=[pl], invoice_items=[it], bank_rows=br, expected=pl['unit_price'], actual=up,
                        difference_czk=r2((up - pl['unit_price']) * q), detail=f'{code}: unit price {up} vs PO {pl["unit_price"]}, qty {q}')
                if pl['qty'] is not None and abs(q - pl['qty']) > 1e-9 and 'quantity_mismatch' in checks:
                    add('quantity_mismatch', inv, files, po_lines=[pl], invoice_items=[it], bank_rows=br, expected=pl['qty'], actual=q,
                        difference_czk=r2((q - pl['qty']) * (pl['unit_price'] if pl['unit_price'] is not None else up)), detail=f'{code}: qty {q} vs PO {pl["qty"]}')
        if total is not None and br:
            paid = r2(-sum(b['amount'] for b in br))
            if len(br) > 1 and 'double_payment' in checks:
                add('double_payment', inv, files, bank_rows=br, expected=total, actual=paid, difference_czk=r2(paid - total),
                    detail=f'{len(br)} outgoing payments with VS {inv.get("vs")}')
            elif len(br) == 1 and abs(paid - total) > 0.005 and 'payment_mismatch' in checks:
                add('payment_mismatch', inv, files, bank_rows=br, expected=total, actual=paid, difference_czk=r2(paid - total),
                    detail='Paid amount differs from invoice total')
    counts = {}
    for f in findings: counts[f['type']] = counts.get(f['type'], 0) + 1
    return {'findings': findings, 'summary': {'invoices_checked': len(groups), 'findings': len(findings), 'by_type': counts,
            'bank_rows_loaded': len(bank), 'po_numbers_loaded': len(pos), 'problems': problems}}

